type Fields<T> = { [K in keyof T]: T[K] };

function pick<T, K extends keyof T>(obj: T, keys: readonly K[]): Pick<T, K> {
  const result = {} as Pick<T, K>;
  for (const k of keys) result[k] = obj[k];
  return result;
}

pick(user, ['id', 'name']); // { id: string; name: string }

